import React,{useState,useEffect} from 'react';import {useQuery} from '@tanstack/react-query';import {supabase} from '../lib/supabase';import {useAuth} from '../contexts/AuthContext';import {TrendingUp,Package,DollarSign,AlertTriangle,Calendar,UserCheck,Clock,ChevronRight,Users,AlertCircle} from 'lucide-react';import {BarChart,Bar,XAxis,YAxis,CartesianGrid,Tooltip,ResponsiveContainer} from 'recharts';import {Link} from 'react-router-dom';import toast from 'react-hot-toast';
function TrialTimer({trialStartedAt}){const [timeLeft,setTimeLeft]=useState('');useEffect(()=>{const update=()=>{const end=new Date(trialStartedAt);end.setDate(end.getDate()+3);const diff=end-new Date();if(diff<=0){setTimeLeft('Trial expired');return;}const days=Math.floor(diff/(86400000));const hours=Math.floor((diff%(86400000))/3600000);const minutes=Math.floor((diff%3600000)/60000);setTimeLeft(`${days}d ${hours}h ${minutes}m`);};update();const i=setInterval(update,60000);return ()=>clearInterval(i);},[trialStartedAt]);return <span className="font-mono text-lg">{timeLeft}</span>;}
export default function Dashboard(){const {staff,storeId}=useAuth();const isAdmin=staff?.role==='admin';const isManager=staff?.role==='manager'||isAdmin;const isCashier=staff?.role==='cashier';const {data:stats,isLoading}=useQuery({queryKey:['dashboard',storeId],queryFn:async()=>{if(!storeId)return null;const today=new Date().toISOString().split('T')[0];const firstOfMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString();const nextWeek=new Date(Date.now()+7*86400000).toISOString();const [todaySales,productCount,lowStock,customerCount,monthSales,settings,expiring,shifts,activeCashiers,saleItems,store]=await Promise.all([supabase.from('sales').select('id,total_amount').eq('store_id',storeId).gte('created_at',today).eq('returned',false),supabase.from('products').select('*',{count:'exact',head:true}).eq('store_id',storeId).eq('is_active',true),supabase.from('products').select('*',{count:'exact',head:true}).eq('store_id',storeId).eq('is_active',true).lte('stock_quantity',10),supabase.from('customers').select('*',{count:'exact',head:true}).eq('store_id',storeId),supabase.from('sales').select('total_amount').eq('store_id',storeId).gte('created_at',firstOfMonth).eq('returned',false),supabase.from('company_settings').select('currency_symbol').eq('store_id',storeId).single(),supabase.from('products').select('id,name,expiry_date,stock_quantity,unit_price').eq('store_id',storeId).not('expiry_date','is',null).lte('expiry_date',nextWeek).limit(10),isAdmin?supabase.from('cash_shifts').select('id,staff:staff_id(full_name),total_sales,transaction_count,start_time,end_time').eq('store_id',storeId).gte('start_time',today):Promise.resolve({data:[]}),isAdmin?supabase.from('cash_shifts').select('staff_id',{count:'exact',distinct:true}).eq('store_id',storeId).is('end_time',null):Promise.resolve({count:0}),supabase.from('sale_items').select('product_id,quantity,product:products(cost_price)').eq('store_id',storeId).gte('created_at',today),supabase.from('stores').select('subscription_status,trial_started_at').eq('id',storeId).single()]);const cur=settings.data?.currency_symbol||'K';const rev=todaySales.data?.reduce((s,i)=>s+i.total_amount,0)||0;let cost=0;if(saleItems.data)for(const i of saleItems.data)cost+=(i.product?.cost_price||0)*i.quantity;const profit=rev-cost;const monthRev=monthSales.data?.reduce((s,i)=>s+i.total_amount,0)||0;const monthProfit=monthRev*(rev>0?profit/rev:0.3);let additionalData={};if(isManager){additionalData={todayProfit:profit,todayCost:cost,monthlyRevenue:monthRev,monthlyProfit:monthProfit,totalProducts:productCount.count||0,totalCustomers:customerCount.count||0,expiringProducts:expiring.data||[],activeShifts:shifts.data||[],activeCashiersCount:activeCashiers.count||0};}return{todaySales:rev,todayTransactions:todaySales.data?.length||0,lowStock:lowStock.count||0,currencySymbol:cur,store:store.data,...additionalData};},enabled:!!storeId});const {data:salesChart}=useQuery({queryKey:['salesChart',storeId],queryFn:async()=>{if(!storeId)return[];const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const ds=d.toISOString().split('T')[0];const {data}=await supabase.from('sales').select('total_amount').eq('store_id',storeId).gte('created_at',ds).lt('created_at',ds+'T23:59:59').eq('returned',false);days.push({date:ds.slice(5),total:data?.reduce((s,i)=>s+i.total_amount,0)||0});}return days;},enabled:!!storeId});const format=v=>`${stats?.currencySymbol||'K'}${v.toFixed(2)}`;if(isLoading||!storeId)return<div className="h-96 flex items-center justify-center">Loading...</div>;return(<div className="p-4 space-y-6 overflow-y-auto h-full"><div className="flex justify-between"><h1 className="text-2xl font-bold">Dashboard</h1><span>{new Date().toLocaleDateString()}</span></div>{stats?.store?.subscription_status==='trialing'&&stats?.store?.trial_started_at&&isAdmin&&(<div className="bg-blue-50 border border-blue-200 rounded-xl p-4"><div className="flex items-center gap-3"><AlertCircle className="text-blue-600" size={24}/><div className="flex-1"><p className="font-medium text-blue-800 text-lg">Free Trial Active</p><p className="text-sm text-blue-600">Time remaining: <TrialTimer trialStartedAt={stats.store.trial_started_at}/></p></div><Link to="/app/settings" className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700">Subscribe Now</Link></div></div>)}{stats?.store?.subscription_status==='expired'&&isAdmin&&(<div className="bg-red-50 border border-red-200 rounded-xl p-4"><div className="flex items-center gap-3"><AlertCircle className="text-red-600" size={24}/><div className="flex-1"><p className="font-medium text-red-800">Trial Expired</p><p className="text-sm text-red-600">Please subscribe to continue.</p></div><Link to="/app/settings" className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700">Subscribe Now</Link></div></div>)}<div className="grid grid-cols-2 md:grid-cols-4 gap-4"><div className="bg-white p-5 rounded-xl shadow"><DollarSign className="text-green-600"/> Today's Sales<p className="text-2xl font-bold">{format(stats.todaySales)}</p><p className="text-xs">{stats.todayTransactions} tx</p></div>{isManager&&<><div className="bg-white p-5 rounded-xl shadow"><TrendingUp className="text-blue-600"/> Today's Profit<p className="text-2xl font-bold">{format(stats.todayProfit||0)}</p><p className="text-xs">Cost: {format(stats.todayCost||0)}</p></div><div className="bg-white p-5 rounded-xl shadow"><AlertTriangle className="text-amber-600"/> Low Stock<p className="text-2xl font-bold text-amber-600">{stats.lowStock}</p></div></>}{!isManager&&<><div className="bg-white p-5 rounded-xl shadow"><Package/> Total Products<p className="text-2xl font-bold">{stats.totalProducts||0}</p></div><div className="bg-white p-5 rounded-xl shadow"><AlertTriangle className="text-amber-600"/> Low Stock<p className="text-2xl font-bold text-amber-600">{stats.lowStock}</p></div></>}<div className="bg-white p-5 rounded-xl shadow"><Users className="text-indigo-600"/> Active Cashiers<p className="text-2xl font-bold text-indigo-600">{stats.activeCashiersCount||0}</p></div></div>{isManager&&<div className="grid grid-cols-1 md:grid-cols-2 gap-4"><div className="bg-white p-5 rounded-xl shadow"><DollarSign/> Monthly Revenue<p className="text-2xl font-bold">{format(stats.monthlyRevenue||0)}</p></div><div className="bg-white p-5 rounded-xl shadow"><TrendingUp/> Monthly Profit<p className="text-2xl font-bold">{format(stats.monthlyProfit||0)}</p></div></div>}{isManager&&stats.expiringProducts?.length>0&&(<div className="bg-amber-50 border border-amber-200 rounded-xl p-5"><h3 className="font-bold text-amber-800 mb-3"><Calendar/> Expiring Soon</h3><div className="grid md:grid-cols-2 gap-3">{stats.expiringProducts.map(p=>{const daysLeft=Math.ceil((new Date(p.expiry_date)-new Date())/86400000);const disc=daysLeft<=1?50:daysLeft<=3?30:daysLeft<=7?15:10;return(<div key={p.id} className="bg-white p-3 rounded border border-amber-200 flex justify-between"><div><p className="font-medium">{p.name}</p><p className="text-sm">Exp: {new Date(p.expiry_date).toLocaleDateString()} · Stock: {p.stock_quantity}</p></div><button onClick={async()=>{await supabase.from('products').update({discount_percent:disc}).eq('id',p.id);toast.success(`Discount ${disc}% applied`);}} className="bg-amber-600 text-white px-3 py-1 rounded text-sm">Apply {disc}%</button></div>);})}</div></div>)}{isAdmin&&stats.activeShifts?.length>0&&(<div className="bg-white rounded-xl shadow overflow-hidden"><div className="p-5 border-b flex items-center gap-2"><UserCheck className="text-green-600"/><h3>Today's Cashier Activity</h3></div><table className="w-full text-sm"><thead><tr><th>Cashier</th><th>Sales</th><th>Tx</th><th>Hours</th><th>Status</th></tr></thead><tbody>{stats.activeShifts.map(shift=>{const hours=shift.end_time?((new Date(shift.end_time)-new Date(shift.start_time))/3600000).toFixed(1):'Active';const active=!shift.end_time;return(<tr key={shift.id}><td>{shift.staff?.full_name}</td><td>{format(shift.total_sales||0)}</td><td>{shift.transaction_count||0}</td><td>{active&&<Clock className="inline w-3 h-3 text-green-600"/>}{hours}</td><td><span className={`px-2 py-1 rounded-full text-xs ${active?'bg-green-100 text-green-800':'bg-gray-100'}`}>{active?'Active':'Closed'}</span></td></tr>);})}</tbody></table></div>)}<div className="grid lg:grid-cols-2 gap-6"><div className="bg-white p-6 rounded-xl shadow"><h3>Sales Last 7 Days</h3><ResponsiveContainer width="100%" height={250}><BarChart data={salesChart}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="date"/><YAxis/><Tooltip formatter={v=>format(v)}/><Bar dataKey="total" fill="#10b981" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div><div className="bg-white p-6 rounded-xl shadow"><h3>Quick Links</h3><div className="grid grid-cols-2 gap-3"><Link to="/app/pos" className="p-3 bg-green-50 rounded-lg flex justify-between"><span>Open POS</span><ChevronRight className="text-green-600"/></Link><Link to="/app/inventory" className="p-3 bg-blue-50 rounded-lg flex justify-between"><span>Inventory</span><ChevronRight className="text-blue-600"/></Link><Link to="/app/sales" className="p-3 bg-purple-50 rounded-lg flex justify-between"><span>Sales</span><ChevronRight className="text-purple-600"/></Link>{isAdmin&&<Link to="/app/discounts" className="p-3 bg-orange-50 rounded-lg flex justify-between"><span>Discounts</span><ChevronRight className="text-orange-600"/></Link>}</div></div></div></div>);}
